<?php declare(strict_types=1);use FastWebsite\Core\View;?>
<section class="page-heading department-heading"><div class="shell"><p class="eyebrow"><?=View::escape(View::setting($siteContent??[],'news.eyebrow','Latest from FAST'))?></p><h1><?=View::escape(View::setting($siteContent??[],'news.title','News'))?></h1></div></section><section class="section"><div class="shell"><?php if($items===[]):?><div class="public-empty"><p><?=View::escape(View::setting($siteContent??[],'news.empty','Published news will appear here.'))?></p></div><?php else:?><div class="department-card-grid"><?php foreach($items as$i):?><article class="department-card"><?php if($i['media_path']):?><img src="<?=View::escape($baseUrl.ltrim(str_replace('public/','',$i['media_path']),'/'))?>" alt="<?=View::escape($i['media_alt_text']??'')?>"><?php endif;?><div><p class="eyebrow"><?=View::escape($i['category_name'])?> · <?=View::escape($i['article_date'])?></p><h2><a href="<?=View::escape($baseUrl)?>news/<?=View::escape($i['slug'])?>"><?=View::escape($i['title'])?></a></h2><p><?=View::escape($i['summary']??'')?></p></div></article><?php endforeach;?></div><?php endif;?></div></section>
